"use strict";

const JourneySound = (() => {
  const Audio = window.AudioContext || window.webkitAudioContext;
  const rate=22050, cycle=12, tau=Math.PI*2;
  const trainHiss=(time,cadence)=>Math.pow(Math.max(0,Math.sin(time*tau*cadence)),5);
  const bell=(time,note)=>{
    if(time<0 || time>1.5)return 0;
    return Math.min(1,time*210)*Math.exp(-4.5*time)*
      (.54*Math.sin(tau*note*time)+.27*Math.sin(tau*note*2.41*time)+.13*Math.sin(tau*note*3.12*time));
  };
  const envelope=(time,duration)=>time<0||time>duration?0:Math.sin(Math.PI*time/duration)**2;

  function birds(time,n){
    let chirp=0;
    for(const offset of [.64,1.02,4.1,6.65,7.04,10.4]){
      const t=time-offset;
      const frequency=1980+offset*105;
      chirp+=envelope(t,.21)*Math.sin(tau*(frequency*t+1630*t*t+10*Math.sin(t*46)))*.16;
      chirp+=envelope(t-.23,.13)*Math.sin(tau*(frequency*(t-.23)+3400*(t-.23)**2))*.095;
    }
    return chirp*(.92+n*.08);
  }
  function murmurs(t,n){
    let sum=0;
    for(let i=0;i<4;i++){
      const a=t+.84*i,d=.39+.088*i,f=115+36*i;
      const words=.65+.35*Math.sin(tau*(3.8+.97*i)*a+.55*Math.sin(a*6));
      const voice=Math.sin(tau*f*a+1.2*Math.sin(tau*d*a))+.34*Math.sin(tau*f*2*a)+.14*Math.sin(tau*f*3*a);
      sum+=voice*words*(.54+.46*Math.sin(tau*d*a))*.027;
    }
    return sum+n*.12*(.55+.45*Math.sin(tau*.67*t));
  }
  const rumble=(t,n,base)=>n*.57+.19*Math.sin(tau*base*t)+.09*Math.sin(tau*base*2*t);
  const traffic=(t,n)=>rumble(t,n,47)*(.55+.45*Math.sin(tau*t/4)**2);
  const loopSounds={
    trail:(t,n,h)=>n*.54+birds(t,h)*.95,
    river:(t,n,h)=>n*.7+h*.11+birds(t,h)*.43,
    station:(t,n,h)=>n*.34+birds(t,h)*.34+murmurs(t,h)*.52,
    factory:(t,n,h)=>rumble(t,n,49)*.47+h*.045+murmurs(t,h)*.34,
    plaza:(t,n,h)=>n*.23+birds(t,h)*.70+murmurs(t,h)*.92,
    market:(t,n,h)=>murmurs(t,h)*1.18+traffic(t,n)*.35,
    stadium:(t,n,h)=>{
      const wave=.68+.32*Math.sin(tau*t/4);
      const whistle=t-3.25;
      return (murmurs(t,h)+h*.15+n*.23)*wave+
        envelope(whistle,.24)*Math.sin(tau*(2160*whistle+215*whistle*whistle))*.11;
    },
    street:(t,n,h)=>traffic(t,n)*.7+murmurs(t,h)*.65,
    heights:(t,n,h)=>n*.75+h*.035+birds(t,h)*.21,
    terminal:(t,n,h)=>traffic(t,n)*.4+murmurs(t,h)*1.2+bell(t-8,712)*.07,
    mule:(t,n,h)=>{
      const beat=t%.75;
      const left=Math.exp(-51*beat),right=beat>.24?Math.exp(-52*(beat-.24)):0;
      return (left+.71*right)*(.47*n+.46*Math.sin(tau*133*beat)+.31*h);
    },
    train:(t,n,h)=>{
      const whistle=envelope(t-.64,1.21);
      const note=411*t-16*(t-.64)**2;
      return rumble(t,n,61)*.56+(n*.47+h*.30)*trainHiss(t,3.5)+
        whistle*(Math.sin(tau*note)+.51*Math.sin(tau*note*1.50))*.14;
    },
    tram:(t,n,h)=>rumble(t,n,68)*.50+h*.32*trainHiss(t,6)+bell(t-.55,760)*.31+bell(t-.87,760)*.24,
    bus:(t,n,h)=>rumble(t,n,52)*.92+.075*Math.sin(tau*105*t+.39*Math.sin(tau*t/3))+h*.05,
    taxi:(t,n,h)=>rumble(t,n,82)*.72+.069*Math.sin(tau*165*t+.50*Math.sin(tau*t/3))+h*.047,
    megabus:(t,n,h)=>rumble(t,n,44)*.86+h*.115+.080*Math.sin(tau*88*t),
    cable:(t,n,h)=>rumble(t,n,54)*.53+h*.095+Math.sin(tau*143*t)*.045+
      Math.exp(-17*(t%3))*h*.39
  };
  const ambience={
    capilla:"trail",ranchos:"river",station:"station",warehouse:"station",coffee:"factory",
    "station-clock":"station","plaza-old":"plaza",plaza:"plaza",market:"market",
    "river-park":"river",bridge:"street",stadium:"stadium",terminal:"terminal",cable:"heights"
  };

  const localRecordings={"audio/bus.mp3":"","audio/megabus.mp3":"","audio/megacable.mp3":"","audio/taxi.mp3":""};
  const recordings={
    bus:{file:"audio/bus.mp3",title:"Diesel bus pulling away",author:"pnwheeler",url:"https://freesound.org/people/pnwheeler/sounds/831721/",detail:"Bus diésel antiguo grabado en Oaxaca."},
    taxi:{file:"audio/taxi.mp3",title:"Car Starting and Accelerating",author:"jackthemurray",url:"https://freesound.org/people/jackthemurray/sounds/433584/",detail:"Arranque y aceleración de un automóvil de referencia."},
    megabus:{file:"audio/megabus.mp3",title:"Bus ride",author:"HenKonen",url:"https://freesound.org/people/HenKonen/sounds/797662/",detail:"Interior de un bus urbano, editado para recrear la marcha y el aire de los frenos."},
    cable:{file:"audio/megacable.mp3",title:"Ski resort – Inside the cable car terminal",author:"schafferdavid",url:"https://freesound.org/people/schafferdavid/sounds/419316/",detail:"Mecanismo de un teleférico en los Alpes franceses, editado para la salida y la llegada de la cabina."}
  };

  function makeBuffer(ctx,key){
    const frames=rate*cycle, blend=Math.round(rate*.086);
    const data=new Float32Array(frames+blend);
    const synth=loopSounds[key];
    let seed=[...key].reduce((s,c)=>s*31+c.charCodeAt(0),27)|0;
    let low=0,mid=0;
    for(let i=0;i<data.length;i++){
      seed^=seed<<13;
      seed^=seed>>>17;
      seed^=seed<<5;
      const sample=(seed>>>0)/2147483648-1;
      low+=.045*(sample-low);
      mid+=.26*(sample-mid);
      data[i]=Math.tanh(synth(i/rate,low*3.9,(mid-low)*2.6));
    }
    const buffer=ctx.createBuffer(1,frames,rate);
    const output=buffer.getChannelData(0);
    output.set(data.subarray(0,frames));
    // Blend the loop boundary so wind and motors do not click at the seam.
    for(let i=0;i<blend;i++){
      const t=i/blend;
      output[i]=data[frames+i]*(1-t)+output[i]*t;
    }
    return buffer;
  }

  class Mixer {
    constructor(){
      this.supported=Boolean(Audio);
      this.enabled=false;
      this.speaking=false;
      this.layers={};
      this.buffers=new Map();
      this.recordedBuffers=new Map();
      this.loading=new Set();
      this.toggleId=0;
    }
    async toggle(){
      if(!this.supported)return;
      const id=++this.toggleId;
      this.failed=false;
      this.enabled=!this.enabled;
      if(this.enabled){
        try{
          if(!this.ctx){
            this.ctx=new Audio();
            this.master=this.ctx.createGain();
            this.master.gain.value=0;
            this.master.connect(this.ctx.destination);
          }
          await this.ctx.resume();
        }catch{
          if(id!==this.toggleId)return;
          this.enabled=false;
          this.failed=true;
        }
      }
      if(id===this.toggleId)this.sync();
    }
    update(era,stop,phase,segment){
      this.background=ambience[era.stops[stop].landmark]||"street";
      this.vehicle=era.vehicle;
      this.segment=segment;
      this.motor=phase==="moving"?this.vehicle:null;
      this.sync();
    }
    static recording(vehicle){return recordings[vehicle];}
    async prepareRecording(key){
      if(this.loading.has(key)||this.recordedBuffers.has(key))return;
      this.loading.add(key);
      try{
        const file=recordings[key].file;
        let bytes;
        if(window.location.protocol==="file:"){
          bytes=Uint8Array.from(atob(localRecordings[file]),character=>character.charCodeAt(0)).buffer;
        }else{
          const response=await fetch(file);
          if(!response.ok)throw new Error("Recording unavailable");
          bytes=await response.arrayBuffer();
        }
        this.recordedBuffers.set(key,await this.ctx.decodeAudioData(bytes));
      }catch{
        this.recordedBuffers.set(key,null);
      }finally{
        this.loading.delete(key);
        this.sync();
      }
    }
    voice(active){
      this.speaking=active;
      this.sync();
    }
    sync(){
      if(!this.ctx||!this.master)return;
      const active=this.enabled&&!document.hidden;
      const time=this.ctx.currentTime;
      this.master.gain.setTargetAtTime(active?(this.speaking ? .26 : .80):0,time,.09);
      if(active && recordings[this.vehicle])this.prepareRecording(this.vehicle);
      const recorded=this.motor?this.recordedBuffers.get(this.motor):null;
      this.layer("background",active?this.background:null,this.motor ? .16 : .27);
      this.layer("motor",active?this.motor:null,recorded ? .58 : .30,recorded);
    }
    layer(slot,key,volume,recorded){
      const current=this.layers[slot], time=this.ctx.currentTime;
      if(current && current.key===key){
        current.gain.gain.setTargetAtTime(volume,time,.18);
        return;
      }
      if(current){
        current.gain.gain.setTargetAtTime(0,time,.08);
        if(!current.ended)current.source.stop(time+.26);
        delete this.layers[slot];
      }
      if(!key || (slot==="motor" && this.loading.has(key)))return;
      let offset=0, speed=1;
      if(recorded&&this.segment){
        const {duration,elapsed,last}=this.segment;
        const sinceFrame=last===null?0:Math.max(0,performance.now()-last);
        offset=recorded.duration*(elapsed+sinceFrame)/duration;
        if(offset>=recorded.duration)return;
        speed=recorded.duration/(duration/1000);
      }
      if(!recorded&&!this.buffers.has(key))this.buffers.set(key,makeBuffer(this.ctx,key));
      const source=this.ctx.createBufferSource();
      const gain=this.ctx.createGain();
      gain.gain.value=0;
      source.buffer=recorded||this.buffers.get(key);
      source.loop=!recorded;
      source.playbackRate.value=speed;
      source.connect(gain).connect(this.master);
      const layer={key,source,gain,ended:false};
      source.onended=()=>{
        layer.ended=true;
        source.disconnect();
        gain.disconnect();
      };
      gain.gain.setTargetAtTime(volume,time,.09);
      source.start(0,offset);
      this.layers[slot]=layer;
    }
  }
  return Mixer;
})();
